/**
 * @method
 * @name setCode
 * @description 기간 from~ to  셋팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    //  기간 from~ to  셋팅
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일주일전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setDepCd
 * @description set Dep Cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDepCd = function() {
    cmb_TeamList.setValue(js_dep_cd);
    cmb_EmpList.setValue(js_emp_no);
    if (scwin.gJobTitle === "40" || js_dep_cd.substring(0, 2) === '2C') {
        // 부서장: 40, ESG팀
        cmb_TeamList.setValue("");
        cmb_EmpList.setValue("");
    } else if (scwin.gJobTitle === "09") {
        // 팀장:09
        cmb_EmpList.setValue("");
    }
};

/**
 * @method
 * @name checkCond
 * @description 일자 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkCond = async function() {
    // 일자 체크
    if (edt_FromDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if (edt_ToDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) === false) {
        return;
    }
    fn_Search();

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

