/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_List.getCellData(Number(obj), "NFAITH_ACPT_NO");
    scwin.gSeq = dts_List.getCellData(Number(obj), "SEQ");
    scwin.gIsurCd = dts_List.getCellData(Number(obj), "ISUR_CD");
    const gProcsTpCd = dts_List.getCellData(Number(obj), "PROCS_TP_CD");
    const gDepmngrApprovYn = dts_List.getCellData(Number(obj), "DEPMNGR_APPROV_YN");
    // alert("부모창:"+gAcptNo+","+ gIsurCd);
};

/**
 * @method
 * @name popupNew
 * @description popup New 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popupNew = async function() {
    scwin.gAcptNo = '';
    scwin.gSeq = '';
    scwin.gIsurCd = '';
    let gGridNewYn = 'Y';
    await scwin.popupDetail(gGridNewYn);
};

/**
 * @method
 * @name popupDetail
 * @description popup Detail 처리
 * @param {String} gGridNewYn gGridNewYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popupDetail = async function(gGridNewYn) {
    let url = "/dsclmgt/ULDSTF37016.gfm?";
    url += "&SEQ=" + scwin.gSeq;
    url += "&ISUR_CD=" + scwin.gIsurCd;
    url += "&GRID_NEW_YN=" + gGridNewYn;
    url += "&EXCPT_TP_CD=" + scwin.gExcptTpCd;
    url += "&frameID=" + frame.FrameID;
    if (await scwin.setParam(scwin.gSeq, scwin.gIsurCd)) {
        $c.frame.path("../../").GWinOpen("ULDSTF37016", url, "불성실공시 적용예외 상세내역", 100, -10, 800, 800 + 40, "");
    }
};

/**
 * @method
 * @name setParam
 * @description child에 param을 넘긴다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) === "undefined") {
        await $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    const argv = scwin.setParam.arguments;
    const argc = scwin.setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (let i = 0; i < argc; i++) {
        // actual arguments
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.setContnId(row);
    if (colid === "DISCLS_TITLE") {
        if (scwin.gAcptNo !== '') {
            await $c.stf.openDisclViewer(scwin.gAcptNo, "R");
        } else {
            await $c.win.alert("해당 공시가 없습니다.");
        }
    } else if (colid === "PROCS_TP_NM") {
        let gGridNewYn = 'N';
        await scwin.popupDetail(gGridNewYn);
    } else if (colid === "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description btn_Search 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    await scwin.checkCond();
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave('ULDSTF37015.xml', SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, {fileName: "불성실예외처리법인관리 목록", type: "8"});
};

/**
 * @method
 * @name cmb_TeamList_onselchange
 * @description cmb_TeamList onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_onselchange = function() {
    dts_emp.sort("DEP_CD", 0);
    // dts_emp.sort(); // W-Craft 주석처리
    dts_emp.UseFilter = true;
    dts_emp.Filter();
};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description emp On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    const vVal = cmb_TeamList.getValue();
    if (vVal === "") {
        // 전체일 경우
        return true;
    } else {
        const vVal2 = dts_emp.getCellData(row, "dep_cd"); // 전체.
        if (vVal2 === "") return true; // 전체.
        return (vVal === vVal2) ? true : false;
    }
};

/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
 * @returns {void}
